package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AllowPasswordGrantVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property allow password grant of tenant config ")
  void test_allow_password_grant_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> AllowPasswordGrantVO.tryFrom(null));
    Assertions.assertEquals(true, AllowPasswordGrantVO.from(true).isAllowPasswordGrant());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> AllowPasswordGrantVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", AllowPasswordGrantVO.from(true).toString());
  }
}
